# Companies map by domain
companies = [
  { domain: "acme.com", name: "Acme Corporation" },
  { domain: "globex.io", name: "Globex" },
  { domain: "initech.dev", name: "Initech" },
  { domain: "umbrella.co", name: "Umbrella Holdings" }
]

# Fetch all pages
page1 = boundary retry 2 { return list_contacts({ page: 1 }) } catch err { return fail("P1", err.message) }
page2 = boundary retry 2 { return list_contacts({ page: 2 }) } catch err { return fail("P2", err.message) }
page3 = boundary retry 2 { return list_contacts({ page: 3 }) } catch err { return fail("P3", err.message) }

all_items = page1.items + page2.items + page3.items

# Process each contact
results = for contact in all_items {
  # Check if phone is already valid E.164: starts with "+1" then exactly 10 digits
  is_valid_phone = regex.test(contact.phone, "^\\+1\\d{10}$")

  # Extract digits from phone
  digits = regex.replace(contact.phone, "[^0-9]", "")
  # It's a US number - should be 10 digits or 11 starting with 1
  new_phone = if !is_valid_phone { "+1" + text.slice(digits, text.length(digits) - 10, text.length(digits)) } else { null }

  # Check company
  company_empty = contact.company == ""
  domain = if company_empty {
    # Extract domain from email: everything after @
    parts = text.split(contact.email, "@")
    parts[1] if parts != [] else ""
  } else { "" }

  # Look up company
  matched_company = if company_empty {
    found = null
    match_fold = fold acc = null for c in companies {
      return c.name if c.domain == domain else acc
    }
    match_fold
  } else { null }

  needs_update = new_phone != null or matched_company != null

  # Only call update if needed
  result = if needs_update {
    boundary retry 2 {
      return update_contact({
        id: contact.id,
        phone: new_phone,
        company: matched_company
      })
    } catch err { return fail("UPDATE_FAILED", contact.id + ": " + err.message) }
  } else { null }

  return {
    id: contact.id,
    phone_fixed: new_phone != null,
    company_filled: matched_company != null
  }
}

phones_fixed = fold acc = 0 for r in results { return acc + (1 if r.phone_fixed else 0) }
companies_filled = fold acc = 0 for r in results { return acc + (1 if r.company_filled else 0) }

return { phones_fixed, companies_filled }

